on conflict (data_base, cd_os) do update set
  nr_contrato = excluded.nr_contrato,
  id_tipo_os = excluded.id_tipo_os,
  ds_tipo_os = excluded.ds_tipo_os,
  cd_baixa = excluded.cd_baixa,
  qtde = excluded.qtde,
  valor_servico = excluded.valor_servico,
  dh_baixa = excluded.dh_baixa,
  tipo_os_consolid = excluded.tipo_os_consolid,
  nm_cidade = excluded.nm_cidade;
